		System.out.println("All prime numbers between 1 and 100:");
		int counter;
		for (int i = 2; i <= 100; i++) {
			counter = 0;
			for (int num = i; num >= 1; num--) {
				if (i % num == 0) {
					counter = counter + 1;
				}
			}
			if (counter == 2) {
				System.out.println(i);
			}
		}
	}

}

